const items = $input.all();
const keys = items
  .map(item => item.json.key)
  .filter(k => !!k);

if (keys.length === 0) {
  return [{ json: { jql: 'project = TKTI AND issuetype in subTaskIssueTypes() AND 1 = 0' } }];
}

// Build: parent in (TKTI-1, TKTI-2, ...)
const keyList = keys.join(', ');

const jql = `
project = TKTI
AND issuetype in subTaskIssueTypes()
AND parent in (${keyList})
AND statusCategory != Done
AND status != "Review and Testing"
`.trim();

return [{ json: { jql } }];

const items = $input.all();
const out = [];

for (const item of items) {
  const issue = item.json;
  const fields = issue.fields || {};

  const assignee = fields.assignee;
  const duedate = fields.duedate;
  const description = fields.description;

  const labels = fields.labels || [];
  const statusName = fields.status?.name || "";
  const issueType = fields.issuetype?.name || "";
  const isSubtask = fields.issuetype?.subtask === true;
  const isDone = statusName === "Done";

  const needsAssignee = !assignee;
  const needsDeadline = !duedate;
  const needsDescription =
    !description ||
    (typeof description === "string" && description.trim().length < 30);

  // Failed QA (review_failed)
  const reviewFailed = labels.includes("review_failed");

  // Needs re-deadline when duedate exists + review failed
  const needsReDeadline = !!duedate && reviewFailed;

  // Parent key for subtasks
  const parentKey = isSubtask ? fields.parent?.key || null : null;

  // -------------------------------------------------------
  // ⚡ NEW: GitHub Branch Link Check (customfield_10071)
  // -------------------------------------------------------
  const branchField = fields.customfield_10071; // <-- your branch field
  const hasBranch = !!branchField;
  const needsBranch = !hasBranch;
  const branchLink = branchField || null;

  // Only keep items needing work
  if (
    needsAssignee ||
    needsDeadline ||
    needsDescription ||
    needsReDeadline ||
    isDone ||
    needsBranch // <-- ADD THIS IF YOU WANT BRANCH CREATION INCLUDED
  ) {
    out.push({
      json: {
        key: issue.key,
        fields,

        needsAssignee,
        needsDeadline,
        needsDescription,
        needsReDeadline,

        // New branch output
        hasBranch,
        needsBranch,
        branchLink,

        isSubtask,
        parentKey,
        statusName,
        labels
      }
    });
  }
}

return out;

// ----------------------------------------------------------
// 1. Extract workload (always last item in array)
// ----------------------------------------------------------
const all = $input.all().map(i => i.json);
const workloadItem = all[all.length - 1];

if (!workloadItem.workload) {
  throw new Error("Workload object not found in last input item!");
}

const workload = workloadItem.workload;

// Filter issues (everything except last workload entry)
const issues = all.slice(0, -1);

// ----------------------------------------------------------
// Config
// ----------------------------------------------------------
const maxLoad = 15; // threshold before skipping an assignee

function getLoad(accountId) {
  if (!accountId) return Infinity;        // missing ID → cannot assign
  return workload[accountId] || 0;        // default 0 if not in map
}

function resolveName(issue, id) {
  if (issue.recommended_assignee_accountId === id) {
    return issue.recommended_assignee_name;
  }
  const hit = issue.top_k_recommendations.find(r => r.accountId === id);
  return hit ? hit.assignee : "Unknown";
}

// ----------------------------------------------------------
// Compute the best assignee for each issue
// ----------------------------------------------------------
const results = [];

for (const issue of issues) {

  // ---- Step 1: recommended assignee ----
  let bestId = issue.recommended_assignee_accountId;
  let bestName = issue.recommended_assignee_name;

  if (getLoad(bestId) < maxLoad) {
    results.push({
      json: {
        key: issue.key,
        issuetype: issue.issuetype,
        project: issue.project,
        description: issue.description,
        predicted_deadline_days: issue.predicted_deadline_days,
        chosen_assignee_name: bestName,
        chosen_assignee_accountId: bestId
      }
    });
    continue;
  }

  // ---- Step 2: search ML top-k fallback ----
  let assigned = false;
  for (const rec of issue.top_k_recommendations) {
    if (getLoad(rec.accountId) < maxLoad) {
      results.push({
        json: {
          key: issue.key,
          issuetype: issue.issuetype,
          project: issue.project,
          description: issue.description,
          predicted_deadline_days: issue.predicted_deadline_days,
          chosen_assignee_name: rec.assignee,
          chosen_assignee_accountId: rec.accountId
        }
      });
      assigned = true;
      break;
    }
  }
  if (assigned) continue;

  // ---- Step 3: fallback to least-loaded person ----
  const sorted = Object.entries(workload).sort((a, b) => a[1] - b[1]); // [ [accountId, load], ... ]
  const fallbackId = sorted[0][0];
  const fallbackName = resolveName(issue, fallbackId);

  results.push({
    json: {
      key: issue.key,
      issuetype: issue.issuetype,
      project: issue.project,
      description: issue.description,
      predicted_deadline_days: issue.predicted_deadline_days,
      chosen_assignee_name: fallbackName,
      chosen_assignee_accountId: fallbackId
    }
  });

}

// Output one item per issue
return results;

// Build workload map
const issues = $input.all();

const workload = {};   // { assigneeAccountId: totalStoryPoints }

for (const item of issues) {
  const issue = item.json;
  const fields = issue.fields || {};

  const assignee = fields.assignee?.accountId;
  const sp = Number(fields.customfield_10016 || 0);

  if (!assignee) continue;

  if (!workload[assignee]) workload[assignee] = 0;
  workload[assignee] += sp;
}

// Export workload
return [
  {
    json: {
      workload
    }
  }
];

// Incoming items list (exactly like the array you posted)
const items = $input.all().map(i => i.json);

// --- 2. Mapping ML -> Jira accountId ---
const accountIdMap = {
  "Maxim Khutornenko": "712020:a7bdea09-c0da-4947-93d0-930e78e73cdc",
