  "Dominic Hamon": "712020:77ed03af-6b83-4da4-a6ba-7e70c70699b6",
  "Stephan Erb": "712020:367c47e2-8fa4-4c99-a06a-b69630063677",
  "Benjamin Mahler": "712020:366caf22-352e-4bdb-bfff-745b3d6a2ecf"
};

// Utility: Remove leading "=" from Jira key/project/issuetype
function cleanString(v) {
  if (typeof v !== "string") return v;
  return v.startsWith("=") ? v.substring(1) : v;
}

const out = [];

for (const item of items) {
  const cleanedKey = cleanString(item.key);
  const cleanedProject = cleanString(item.project);
  const cleanedType = cleanString(item.issuetype);

  // Map recommended assignee → accountId
  const recommendedName = item.recommended_assignee;
  const recommendedAccountId = accountIdMap[recommendedName] ?? null;

  // Convert top_k list → accountId
  const topKConverted = item.top_k_recommendations.map(rec => ({
    assignee: rec.assignee,
    accountId: accountIdMap[rec.assignee] ?? null,
    probability: rec.probability
  }));

  out.push({
    json: {
      key: cleanedKey,
      issuetype: cleanedType,
      project: cleanedProject,
      description: item.description,
      predicted_deadline_days: item.predicted_deadline_days,

      recommended_assignee_name: recommendedName,
      recommended_assignee_accountId: recommendedAccountId,

      top_k_recommendations: topKConverted
    }
  });
}

return out;

const items = $input.all().map(i => i.json);

const parents = [];
const subtasks = [];

// Separate parent issues vs subtasks
for (const item of items) {
  const fields = item.fields || {};

  if (fields.issuetype?.subtask === true) {
    // It's a subtask
    subtasks.push(item);
  } else {
    // It's a parent issue
    parents.push(item);
  }
}

// Build parent map: parentKey → parentFields
const parentMap = {};
for (const p of parents) {
  parentMap[p.key] = {
    assignee: p.Assignee || null,
    duedate: p["Due date"] || p.duedate || null,
    labels: p.Labels || []
  };
}

const out = [];

for (const sub of subtasks) {
  const sf = sub.fields || {};

  const subtaskKey = sub.key;
  const subtaskId = sub.id || null;

  const parentKey = sf.parent?.key;
  const parent = parentMap[parentKey] || {};

  const finalAssignee = parent.assignee || null;
  const finalDueDate = sf.duedate || parent.duedate || null;

  const finalLabels = [
    ...(sf.labels || []),
    ...(parent.labels || []),
  ];

  out.push({
    json: {
      subtaskKey,
      subtaskId,
      parentKey,
      finalAssignee,
      finalDueDate,
      finalLabels
    }
  });
}

return out;

const items = $input.all();
const out = [];

for (const item of items) {
  const ref = item.json.ref || "";
  const match = ref.match(/^refs\/heads\/(.+)$/);

  if (!match) continue; // skip if invalid ref

  const branchName = match[1];

  // Extract Jira key (SCRUM-9, SCRUM-7, etc.)
  const issueKey = branchName.split("-")[0] + "-" + branchName.split("-")[1];

  // Build GitHub link
  const githubLink = `https://github.com/MRHP1/N8N-IntelliFlow/tree/${branchName}`;

  out.push({
    json: {
      key: issueKey,
      branchName,
      githubLink
    }
  });
}

return out;

const items = $input.all();   // <-- get ALL incoming items
const out = [];

for (const item of items) {
  const issue = item.json;
  const fields = issue.fields || {};

  const branchLink = fields["customfield_10071"]; // your branch link CF
  const key = issue.key;
  const summary = fields.summary || "";

  // sanitize summary → lowercase, hyphens only
  const clean = summary
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

  // final branch name
  const branchName = `${key}-${clean}`;

  out.push({
    json: {
      key,
      summary,
      branchName,
      branchLink,
      needsBranch: !branchLink
    }
  });
}

return out;

// Find the GitHub SHA item
const shaItem = $input.all().find(i => i.json.object?.sha);

if (!shaItem) {
  throw new Error("SHA not found in input!");
}

const sha = shaItem.json.object.sha;

// Return the SHA for all next nodes
return [{ json: { sha } }];

const items = $input.all();
const out = [];

for (const item of items) {
  const issue = item.json;
  const fields = issue.fields || {};

  const assignee = fields.assignee;
  const duedate = fields.duedate;
  const description = fields.description;

  const labels = fields.labels || [];
  const statusName = fields.status?.name || "";
  const isSubtask = fields.issuetype?.subtask === true;

  // Parent key for subtasks
  const parentKey = isSubtask ? fields.parent?.key || null : null;

  // Branch field
  const branchField = fields.customfield_10071;
  const hasBranch = !!branchField;
  const branchLink = branchField || null;

  // -------------------------------------------------------
  // FILLED CHECKS
  // -------------------------------------------------------
  const isAssigneeFilled = !!assignee;
  const isDeadlineFilled = !!duedate;
  const isDescriptionFilled =
    !!description && description.toString().trim().length >= 30;

  const isToDoStatus = statusName === "To Do";

  // -------------------------------------------------------
  // ONLY INCLUDE ISSUES THAT ARE FULLY COMPLETE & IN TO DO
  // -------------------------------------------------------
  const isReady =
    isAssigneeFilled &&
    isDeadlineFilled &&
    isDescriptionFilled &&
    isToDoStatus;

  if (isReady) {
    out.push({
      json: {
        key: issue.key,

        // status reference
        statusName,

        // completeness flags
        isAssigneeFilled,
        isDeadlineFilled,
        isDescriptionFilled,
        isToDoStatus,

        // branch info (optional)
        hasBranch,
        branchLink,

        isSubtask,
        parentKey,
        labels
      }
    });
  }
}

return out;

let items = $input.all();

// Normalize input: detect embedded array or multiple items
let arr = [];
if (items.length > 1) {
    arr = items.map(i => i.json);
} else if (Array.isArray(items[0].json)) {
    arr = items[0].json;
} else {
    arr = [items[0].json];
}

// Build output
let out = [];

for (const pr of arr) {
    const url = pr.url || null;
    const number = pr.number || null;
    const state = pr.state || null;
    const body = pr.body || null;
    const title = pr.title || null;

    // detect branch name
    const branch = pr.head?.ref || null;

    // detect jira key from branch or title
    const jiraKey =
        branch?.match(/[A-Z]+-\d+/)?.[0] ||
        title?.match(/[A-Z]+-\d+/)?.[0] ||
        null;

    // detect review status
    const reviewState = pr.state || null; // CHANGES_REQUESTED, APPROVED, etc.

    // automation flags
    const needsInitialReview = reviewState === "open";  
    const needsFixes = reviewState === "CHANGES_REQUESTED";
    const isApproved = reviewState === "APPROVED";
    const isMerged = pr.merged_at ? true : false;
    const isRejected = reviewState === "DISMISSED" || reviewState === "REJECTED";

    out.push({
        json: {
            prNumber: number,
            prUrl: url,
            htmlUrl: pr.html_url || null,

            title,
            body,
            branch,
            jiraKey,

            // PR state
            state: pr.state,
            isMerged,
            isRejected,

            // Review state
            reviewState,
            needsInitialReview,
            needsFixes,
            isApproved,

            // Useful URLs for later workflow steps
            commitsUrl: pr.commits_url || null,
            issueCommentsUrl: pr.comments_url || null,
            reviewCommentsUrl: pr.review_comments_url || null,
            statusUrl: pr.statuses_url || null,
        }
    });
}

return out;

let items = $input.all().map(i => i.json);

// Group by PR number
const prMap = {};

for (const r of items) {
    const num = r.prNumber;
    if (!prMap[num]) prMap[num] = {
        prNumber: num,
        prUrl: r.prUrl,
        htmlUrl: r.htmlUrl,
        title: r.title,
        branch: r.branch,
        jiraKey: r.jiraKey,

        // Collected review states
        reviews: [],

        // URLs
        commitsUrl: r.commitsUrl,
        issueCommentsUrl: r.issueCommentsUrl,
        reviewCommentsUrl: r.reviewCommentsUrl,
        statusUrl: r.statusUrl,
    };

    prMap[num].reviews.push({
        state: r.reviewState,
        body: r.body
    });
}

// Build final output
const out = [];

for (const num in prMap) {
    const pr = prMap[num];

    const lastReview = pr.reviews[pr.reviews.length - 1] || {
        state: null,
        body: null
    };

    const lastState = lastReview.state;
    const lastBody = lastReview.body;

    out.push({
        json: {
            prNumber: pr.prNumber,
            jiraKey: pr.jiraKey,
            title: pr.title,
            branch: pr.branch,
            prUrl: pr.prUrl,
            htmlUrl: pr.htmlUrl,

            // Final review summary
            latestReviewState: lastState,
            latestReviewBody: lastBody,

            // Automation flags
            needsInitialReview: pr.reviews.length === 0,
            needsFixes: lastState === "CHANGES_REQUESTED",
            isApproved: lastState === "APPROVED",

            // ML model input hooks
            modelDescriptionInput: lastBody || "",
            modelDeadlineInput: lastBody || "",

            // URLs
            commitsUrl: pr.commitsUrl,
            issueCommentsUrl: pr.issueCommentsUrl,
            reviewCommentsUrl: pr.reviewCommentsUrl,
            statusUrl: pr.statusUrl
        }
    });
}

return out;
